DROP POLICY IF EXISTS "Authenticated can read dues" ON public.monthly_dues;
CREATE POLICY "Members can read dues" ON public.monthly_dues FOR SELECT TO authenticated USING (public.is_club_member(auth.uid()) OR public.has_role(auth.uid(),'admin'));
DROP POLICY IF EXISTS "Authenticated can read mom_votes" ON public.mom_votes;
CREATE POLICY "Members can read mom_votes" ON public.mom_votes FOR SELECT TO authenticated USING (public.is_club_member(auth.uid()) OR public.has_role(auth.uid(),'admin'));
DROP POLICY IF EXISTS "Authenticated can read worst_votes" ON public.worst_votes;
CREATE POLICY "Members can read worst_votes" ON public.worst_votes FOR SELECT TO authenticated USING (public.is_club_member(auth.uid()) OR public.has_role(auth.uid(),'admin'));
DROP POLICY IF EXISTS "club_settings_read_authenticated" ON public.club_settings;
CREATE POLICY "club_settings_read_members" ON public.club_settings FOR SELECT TO authenticated USING (public.is_club_member(auth.uid()) OR public.has_role(auth.uid(),'admin'));
DROP POLICY IF EXISTS "Authenticated can read profiles" ON public.profiles;
CREATE POLICY "Members or owner can read profiles" ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid() OR public.is_club_member(auth.uid()) OR public.has_role(auth.uid(),'admin'));
DROP POLICY IF EXISTS "squad_depth_select_all" ON public.squad_depth;
CREATE POLICY "squad_depth_select_members" ON public.squad_depth FOR SELECT TO authenticated USING (public.is_club_member(auth.uid()) OR public.has_role(auth.uid(),'admin'));
DROP POLICY IF EXISTS "Authenticated can read predictions" ON public.match_predictions;
CREATE POLICY "Members can read predictions" ON public.match_predictions FOR SELECT TO authenticated USING (public.is_club_member(auth.uid()) OR public.has_role(auth.uid(),'admin'));
DROP POLICY IF EXISTS "Authenticated can read attendance" ON public.match_attendance;
CREATE POLICY "Members can read attendance" ON public.match_attendance FOR SELECT TO authenticated USING (public.is_club_member(auth.uid()) OR public.has_role(auth.uid(),'admin'));
DROP POLICY IF EXISTS "Anyone can read players" ON public.players;
CREATE POLICY "Members can read players" ON public.players FOR SELECT TO authenticated USING (public.is_club_member(auth.uid()) OR public.has_role(auth.uid(),'admin'));
DROP POLICY IF EXISTS "Anyone can read team_history" ON public.team_history;
CREATE POLICY "Members can read team_history" ON public.team_history FOR SELECT TO authenticated USING (public.is_club_member(auth.uid()) OR public.has_role(auth.uid(),'admin'));